BEGIN;

-- Run once (seed_runs). Brings the Puducherry VS 2011-2021 rows of an existing DB to the real ECI values before the
-- Puducherry VS seeds run: deletes the old rows ECI does not have (decided in scraper/data/py/decisions.json),
-- fixes votes/status/margin, candidate names/party/age, constituency type/electors/turnout/phase, and renames
-- auto-created single-candidacy persons still carrying the old name. The VS seeds then insert the missing
-- candidates. On a fresh DB there are no Puducherry rows yet: the body is skipped and only the marker is written.
-- Generated by scraper/src/bihar/generate-cli.ts. Do not edit by hand.
SELECT NOT EXISTS (SELECT 1 FROM seed_runs WHERE name = 'seed_py_corrections_v1')
   AND EXISTS (SELECT 1 FROM constituencies WHERE election_id = 'b1c2d3e4-f5a6-7890-1234-567890ab2011')
   AS seed_apply \gset
\if :seed_apply

-- Pre-flight: this DB must hold exactly the old seeds' Puducherry candidates, with their seeded parties.
CREATE TEMP TABLE py_old_seed (id uuid PRIMARY KEY, party_id text) ON COMMIT DROP;
