DO $$
DECLARE unknown int; moved int;
BEGIN
  SELECT count(*) INTO unknown FROM candidates c WHERE c.election_id IN ('b1c2d3e4-f5a6-7890-1234-567890ab2011', 'b1c2d3e4-f5a6-7890-1234-567890ab2016', 'b1c2d3e4-f5a6-7890-1234-567890ab2021')
    AND NOT EXISTS (SELECT 1 FROM py_old_seed o WHERE o.id = c.id);
  SELECT count(*) INTO moved FROM candidates c JOIN py_old_seed o ON o.id = c.id WHERE c.party_id IS DISTINCT FROM o.party_id;
  IF unknown > 0 OR moved > 0 THEN
    RAISE EXCEPTION 'seed_py_corrections_v1: % Puducherry candidates are not in the old seeds and % changed party since; reconcile them first (docs/DEPLOYMENT.md 5.0a)', unknown, moved;
  END IF;
END $$;

